"""Round-6 theory: slide topics still thin (set operations on 8.0.28, LIKE/REGEXP, lookup-table joins, outer join traps). Examples are read-only."""

def T(number, question, answer, tags, example, pattern='computed'):
    return dict(id='TH5-%03d' % number, question=question, answer=answer,
                tags=tags.split('|'), examples=[example] if example else [],
                pattern=pattern, mistakes=[])

THEORY5 = [
 T(1, 'Why do you filter on a status name through its lookup table instead of a hard-coded id?',
   'A lookup table maps a numeric code to a meaning, and joining to it lets the query say WHERE Status Name = Closed, which stays correct if codes are renumbered and documents itself. Use an inner join when only existing codes matter and a LEFT JOIN from the lookup table when every status must appear, even with zero rows. Hard-coded ids are acceptable only when the exam states the numeric meaning.',
   'lookup table|status|join|hard coded id|left join',
   "SELECT s.`Status Name`, COUNT(o.`Order ID`) FROM `orders status` s LEFT JOIN orders o ON o.`Status ID` = s.`Status ID` GROUP BY s.`Status ID`, s.`Status Name`;",
   'left_join'),
 T(2, 'Why do NULL comparisons in WHERE drop rows that look like they should match?',
   'Any comparison with NULL yields UNKNOWN, and WHERE keeps only rows where the condition is TRUE, so both x = NULL and x <> 5 lose rows whose x is NULL. Use IS NULL and IS NOT NULL, the NULL-safe equality operator <=>, or COALESCE when a default is acceptable. NOT (x > 5) does not return the NULL rows either, so add an explicit OR x IS NULL when they are wanted.',
   'null|three valued logic|is null|null safe|unknown',
   "SELECT (SELECT COUNT(*) FROM orders WHERE `Payment Type` <> 'Check') AS not_check, (SELECT COUNT(*) FROM orders WHERE `Payment Type` IS NULL) AS missing;",
   'null_handling'),
 T(3, 'A query uses LEFT JOIN to list all customers and count orders. Why can COUNT(*) return 1 for a customer with no orders? Explain how counting a non-NULL order key fixes the result.',
   'A LEFT JOIN keeps a customer with no orders by adding one row whose order columns are all NULL. COUNT(*) counts rows, so that single padding row gives 1 instead of 0. COUNT(o.`Order ID`) counts only non-NULL values, and the padding row has a NULL key, so a customer without orders correctly gets 0. Count a column from the optional side that is never NULL in a real row, usually its primary key.',
   'left join|count star|count column|null padding|zero orders',
   "SELECT c.ID, COUNT(*) AS wrong_count, COUNT(o.`Order ID`) AS right_count FROM customers c LEFT JOIN orders o ON o.`Customer ID` = c.ID GROUP BY c.ID;",
   'left_join'),
 T(4, 'After joining orders to order details, a query calculates SUM(Shipping Fee) per customer. Explain why the result may be too large. Would SUM(DISTINCT Shipping Fee) always fix the problem? Explain briefly.',
   'Shipping Fee belongs to the order, but the join repeats the order row once for every detail line, so the fee is added once per line and the total is inflated. SUM(DISTINCT Shipping Fee) is not a safe fix: it drops legitimate repeats, so two different orders that happen to have the same fee are counted only once. The reliable fix is to aggregate the detail lines to one row per order first (or sum the fee over orders alone) and then join or sum.',
   'fan out|sum distinct|join duplicates|shipping fee|double counting',
   "SELECT o.`Customer ID`, SUM(o.`Shipping Fee`) AS inflated, (SELECT SUM(x.`Shipping Fee`) FROM orders x WHERE x.`Customer ID` = o.`Customer ID`) AS correct FROM orders o JOIN `order details` d ON d.`Order ID` = o.`Order ID` GROUP BY o.`Customer ID`;",
   'multi_agg'),
 T(5, 'When should a database rule use a trigger rather than an explicitly called stored procedure?',
   'Use a trigger when a row-level rule or audit action must run automatically for every matching INSERT, UPDATE or DELETE, regardless of which client issued it. Use a procedure for an explicitly invoked workflow with input or output parameters and potentially several statements. Prefer a declarative constraint for a rule it can express, because triggers introduce implicit side effects and procedures can be bypassed by direct writes.',
   'trigger|procedure|automatic|call|constraint', None),
 T(6, 'Compare DELETE, TRUNCATE and DROP for removing data, preserving a table and resetting generated IDs.',
   'DELETE removes matching rows and accepts WHERE; on InnoDB it can be rolled back inside a transaction and fires DELETE triggers. TRUNCATE removes every row, keeps the table definition, resets AUTO_INCREMENT, implicitly commits and does not fire DELETE triggers. DROP TABLE removes the table definition as well as its data and normally implicitly commits; temporary-table DDL has special rules. Neither TRUNCATE nor DROP TABLE is a substitute for a filtered DELETE.',
   'delete|truncate|drop|auto_increment|implicit commit', None),
 T(7, 'Can ROLLBACK undo CREATE TABLE, ALTER TABLE or TRUNCATE in MySQL 8.0.28?',
   'Ordinary CREATE TABLE, ALTER TABLE and TRUNCATE implicitly commit and cannot be undone by a later ROLLBACK. MySQL atomic DDL means the individual DDL operation is crash-safe, not that application transactions can roll it back. CREATE TEMPORARY TABLE and DROP TEMPORARY TABLE do not implicitly commit, but their table creation or removal still is not rolled back. Keep DDL out of a transaction intended to protect a group of data changes.',
   'rollback|ddl|implicit commit|atomic ddl|temporary table', None),
 T(8, 'How does SIGNAL SQLSTATE 45000 reject an invalid value inside a trigger, and what does a handler change?',
   "SIGNAL SQLSTATE '45000' raises a user-defined exception, optionally with MESSAGE_TEXT describing the violated rule. In an InnoDB BEFORE trigger an unhandled exception fails the triggering statement rather than saving the invalid row; it does not necessarily roll back earlier successful statements in the transaction. A matching handler can catch the exception, so transaction code must deliberately decide whether to roll back the whole transaction or to a savepoint. Validate NULL explicitly because comparisons such as price < 0 do not reject NULL.",
   'signal|sqlstate|45000|trigger|handler|null', None),
 T(9, 'Why must a cursor loop test its NOT FOUND handler flag immediately after FETCH, and when is SUM preferable?',
   'FETCH past the last row invokes the NOT FOUND handler and does not provide a new value to process. Test the handler flag before using the fetched variable, otherwise a loop can process a stale value once more. Declare local variables before cursors and handlers after cursors, then OPEN, FETCH in a loop and CLOSE. Prefer a set-based aggregate when the task is just a total; a cursor is justified only when per-row procedural work is required.',
   'cursor|fetch|not found|handler|sum|loop',
   'SELECT COALESCE(SUM(`List Price`),0) FROM products;'),
 T(10, 'How do COMMIT, full ROLLBACK and ROLLBACK TO SAVEPOINT differ during a two-account transfer?',
   'COMMIT persists all surviving changes in the current transaction, while a full ROLLBACK undoes its uncommitted InnoDB changes. SAVEPOINT names an intermediate position, and ROLLBACK TO SAVEPOINT undoes later changes without committing or ending the transaction. Lock both account rows in a consistent order, verify that both exist and that funds suffice, then update both balances as one unit. MySQL does not support nested transactions: START TRANSACTION inside an active transaction commits the current one.',
   'transaction|commit|rollback|savepoint|transfer|for update', None),
]
